export interface ConnectorConfig {
  asanaAccessToken: string
  workspaceGid: string
  fetch?: typeof fetch
}

export interface JotformSubmissionPayload {
  formTitle: string
  field_answers: Record<string, string>
}

export interface AsanaTaskResponse {
  gid: string
  name: string
  description: string
  resource_type: string
}

export interface HandleResult {
  taskId: string
  taskName: string
}

export async function handle(
  payload: JotformSubmissionPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.formTitle || typeof payload.formTitle !== 'string') {
    throw new Error('Missing required field: formTitle')
  }
  if (!payload.field_answers || typeof payload.field_answers !== 'object') {
    throw new Error('Missing required field: field_answers')
  }

  const description = JSON.stringify(payload.field_answers, null, 2)

  const requestBody = {
    data: {
      name: payload.formTitle,
      description,
      workspace: config.workspaceGid,
    },
  }

  const response = await fetchImpl('https://app.asana.com/api/1.0/tasks', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.asanaAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (!response.ok) {
    throw new Error(
      `Asana API error: ${response.status} ${response.statusText} for POST https://app.asana.com/api/1.0/tasks`,
    )
  }

  const result = (await response.json()) as { data: AsanaTaskResponse }
  return {
    taskId: result.data.gid,
    taskName: result.data.name,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, JotformSubmissionPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      asanaAccessToken: 'test-token',
      workspaceGid: '1234567890123456',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmissionPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.taskId).toBe('9876543210987654321')
    expect(result.taskName).toBe('Customer Feedback Survey')
  })
})

describe('handle', () => {
  it('maps formTitle to name and field_answers to JSON description', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://app.asana.com/api/1.0/tasks' && req.method === 'POST'
        ? jsonResponse(TARGET_ENDPOINTS[0].response, 201)
        : jsonResponse({ error: 'not found' }, 404),
    )

    const payload: JotformSubmissionPayload = {
      formTitle: 'Test Form',
      field_answers: { q1: 'answer1', q2: 'answer2' },
    }
    const config: ConnectorConfig = {
      asanaAccessToken: 'token-123',
      workspaceGid: 'ws-456',
      fetch,
    }

    const result = await handle(payload, config)

    expect(calls).toHaveLength(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://app.asana.com/api/1.0/tasks')
    expect(call.headers.get('authorization')).toBe('Bearer token-123')
    expect(call.json).toEqual({
      data: {
        name: 'Test Form',
        description: '{\n  "q1": "answer1",\n  "q2": "answer2"\n}',
        workspace: 'ws-456',
      },
    })
    expect(result.taskId).toBe('9876543210987654321')
  })

  it('throws on missing formTitle', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { field_answers: { a: '1' } } as unknown as JotformSubmissionPayload
    const config: ConnectorConfig = { asanaAccessToken: 't', workspaceGid: 'w', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: formTitle')
  })

  it('throws on missing field_answers', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { formTitle: 'Test' } as unknown as JotformSubmissionPayload
    const config: ConnectorConfig = { asanaAccessToken: 't', workspaceGid: 'w', fetch }

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: field_answers')
  })

  it('throws on non-2xx response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'unauthorized' }, 401))
    const payload: JotformSubmissionPayload = { formTitle: 'Test', field_answers: {} }
    const config: ConnectorConfig = { asanaAccessToken: 'bad', workspaceGid: 'w', fetch }

    await expect(handle(payload, config)).rejects.toThrow(
      'Asana API error: 401 Unauthorized for POST https://app.asana.com/api/1.0/tasks',
    )
    expect(calls).toHaveLength(1)
  })

  it('uses injected fetch and returns task id and name', async () => {
    const customResponse = {
      data: {
        gid: 'custom-task-id',
        name: 'Custom Task',
        description: '{}',
        resource_type: 'task',
      },
    }
    const { fetch, calls } = fakeFetch(() => jsonResponse(customResponse, 201))
    const payload: JotformSubmissionPayload = { formTitle: 'Custom', field_answers: {} }
    const config: ConnectorConfig = { asanaAccessToken: 't', workspaceGid: 'w', fetch }

    const result = await handle(payload, config)

    expect(result.taskId).toBe('custom-task-id')
    expect(result.taskName).toBe('Custom Task')
    expect(calls).toHaveLength(1)
  })
})

